async function getUser(id) {
  const key = `user:${id}`;

  // 1. Check cache
  const cached = await redis.get(key);
  if (cached) {
    return JSON.parse(cached);  // cache HIT
  }

  // 2. Cache MISS — load from database
  const user = await db.users.findById(id);
  if (!user) return null;

  // 3. Populate cache with TTL
  await redis.set(key, JSON.stringify(user), 'EX', 300);  // 5 minutes

  return user;
}

async function updateUser(id, data) {
  // 1. Write to database (source of truth)
  const updated = await db.users.update(id, data);

  // 2. Write to cache simultaneously
  await redis.set(`user:${id}`, JSON.stringify(updated), 'EX', 300);

  return updated;
}

async function updateUser(id, data) {
  // Update DB
  const updated = await db.users.update(id, data);

  // Invalidate cache — next read will be a miss and re-populate
  await redis.del(`user:${id}`);

  return updated;
}

// For related cache entries, use a pattern
async function invalidateUserCaches(id) {
  // Pipeline multiple deletes
  const pipeline = redis.pipeline();
  pipeline.del(`user:${id}`);
  pipeline.del(`user:${id}:profile`);
  pipeline.del(`user:${id}:permissions`);
  await pipeline.exec();
}

async function getWithLock(key, ttl, fetchFn) {
  // Check cache
  const cached = await redis.get(key);
  if (cached) return JSON.parse(cached);

  // Try to acquire lock
  const lockKey = `lock:${key}`;
  const acquired = await redis.set(lockKey, '1', 'NX', 'EX', 10);

  if (!acquired) {
    // Another worker is recomputing — wait and retry
    await new Promise(r => setTimeout(r, 100));
    return getWithLock(key, ttl, fetchFn);
  }

  try {
    // Recheck cache after acquiring lock
    const rechecked = await redis.get(key);
    if (rechecked) return JSON.parse(rechecked);

    const value = await fetchFn();
    await redis.set(key, JSON.stringify(value), 'EX', ttl);
    return value;
  } finally {
    await redis.del(lockKey);
  }
}
